const notificationPreferences = new Map<string, boolean>()

export async function getNotificationsEnabled(userId: string): Promise<boolean> {
  return notificationPreferences.get(userId) ?? false
}

export async function setNotificationsEnabled(
  userId: string,
  enabled: boolean
): Promise<void> {
  notificationPreferences.set(userId, enabled)
}

