'use server'

import { refresh } from 'next/cache'
import {
  getNotificationsEnabled,
  setNotificationsEnabled,
} from './lib/preferences'

// Replace with the authenticated user's id from your session.
const CURRENT_USER_ID = 'demo-user'

export async function toggleNotifications() {
  const enabled = await getNotificationsEnabled(CURRENT_USER_ID)
  await setNotificationsEnabled(CURRENT_USER_ID, !enabled)

  // Refresh the client router so the current page re-renders with the
  // updated preference, without navigating away.
  refresh()
}

